//! Bounded RSS2 audio enclosure projection; no network or markup rendering.
use crate::{Result,epub_xml::{self,Event}};use serde_json::{json,Value};
pub(crate) fn parse(a:&Value)->Result<Value>{let source=a["xml"].as_str().filter(|s|s.len()<=131072).ok_or("Podcast XML exceeds128KiB")?;if source.contains("<!DOCTYPE"){return Err("Podcast DTDs are unsupported".into())}let events=epub_xml::parse(source)?;let mut path=Vec::new();let mut episodes=Vec::new();let mut title=String::new();let mut show=String::new();let mut enclosure=None;let mut ids=std::collections::BTreeSet::new();for event in events{match event{
 Event::Open(tag,attrs)=>{path.push(tag.clone());if path.len()==1&&(tag!="rss"||attrs.get("version").map(String::as_str)!=Some("2.0")){return Err("Use an RSS2 podcast feed".into())}if path==["rss","channel","item"]{if episodes.len()>=40{return Err("Podcast feed exceeds40 episodes; use a bounded feed page".into())}title.clear();enclosure=None;}
 if path==["rss","channel","item","enclosure"]{if enclosure.is_some(){return Err("Ambiguous multiple podcast enclosures".into())}let url=attrs.get("url").ok_or("Missing enclosure URL")?;crate::sdk_http::origin(url)?;let mime=attrs.get("type").ok_or("Missing enclosure MIME")?;if !["audio/mpeg","audio/mp4","audio/ogg","audio/aac","audio/flac","audio/wav","audio/x-m4a"].contains(&mime.as_str()){return Err("Unsupported podcast enclosure MIME".into())}let size=attrs.get("length").and_then(|s|s.parse::<u64>().ok()).filter(|n|*n>0&&*n<=1073741824).ok_or("Invalid enclosure length")?;enclosure=Some(json!({"url":url,"mime":mime,"size":size}));}},
 Event::Text(s)=>{if path==["rss","channel","title"]{show.push_str(&s)}if path==["rss","channel","item","title"]{title.push_str(&s)}if show.len()>400||title.len()>800{return Err("Podcast title exceeds limits".into())}},
 Event::Close(_)=>{if path==["rss","channel","item"]{if let Some(mut e)=enclosure.take(){let url=e["url"].as_str().unwrap().to_string();if !ids.insert(url){return Err("Duplicate podcast enclosure".into())}let t=title.trim();if t.is_empty(){return Err("Missing episode title".into())}e["title"]=json!(t);episodes.push(e);}}path.pop();}
 }}if show.trim().is_empty(){return Err("Missing podcast channel title".into())}Ok(json!({"title":show.trim(),"episodes":episodes}))}
#[cfg(test)]mod tests{use super::*;fn feed(item:&str)->Value{json!({"xml":format!("<rss version='2.0'><channel><title>Demo &amp; café</title>{item}</channel></rss>")})}#[test]fn podcasts_extract_audio_without_description_markup(){let v=parse(&feed("<item><title>Episode</title><description><![CDATA[<script>ignored</script>]]></description><enclosure url='https://audio.example.org/a.mp3' type='audio/mpeg' length='123'/></item>")).unwrap();assert_eq!(v["title"],"Demo & café");assert_eq!(v["episodes"][0]["size"],123);assert!(v["episodes"][0].get("description").is_none());}#[test]fn podcasts_reject_unsafe_ambiguous_and_oversized_sources(){for url in["http://audio.example.org/a","https://user@audio.example.org/a","https://127.0.0.1/a"]{assert!(parse(&feed(&format!("<item><title>x</title><enclosure url='{url}' type='audio/mpeg' length='1'/></item>"))).is_err());}assert!(parse(&json!({"xml":"<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///secret'>]><rss/>"})).is_err());let item="<item><title>x</title><enclosure url='https://audio.example.org/a' type='audio/mpeg' length='1'/></item>";assert!(parse(&feed(&item.repeat(2))).is_err());assert!(parse(&json!({"xml":"x".repeat(131073)})).is_err());}}
